    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t2 = x[2] * x[2];
        let t4 = x[4] * x[7];
        let t7 = x[0].mul_add(x[0], t1);
        let t8 = (-x[9]).mul_add(x[9], t2);
        let t9 = t7 + t8;
        let t10 = x[3].mul_add(x[6], t4);
        let t11 = x[5].mul_add(x[8], t10);
        let t13 = (-t11).mul_add(T::from_i64(2), t9);
        t13
    }

