    /// The identity map on `Motor`: a `Motor` with one open `Motor` slot.
    #[inline(always)]
    pub fn slot() -> Motor<(Motor,), T> {
        Motor { c: core::array::from_fn(|i| core::array::from_fn(|j| if i == j { T::one() } else { T::zero() })) }
    }

    /// Coefficient of `1`.
    #[inline(always)]
