impl<T: gx::Real> Even<(), T> {
    /// The squared norm: the scalar part of `x ~x`.
    #[inline(always)]
    pub fn norm_squared(self) -> T {
        let x = self.c;
        let t1 = x[1] * x[1];
        let t3 = x[3] * x[3];
        let t5 = x[5] * x[8];
        let t8 = x[11] * x[11];
        let t10 = x[13] * x[13];
        let t11 = x[14] * x[15];
        let t12 = x[0].mul_add(x[0], t1);
        let t13 = x[2].mul_add(x[2], t3);
        let t14 = t12 + t13;
        let t15 = x[10].mul_add(x[10], t8);
        let t16 = x[12].mul_add(x[12], t10);
        let t17 = t15 + t16;
        let t18 = t14 - t17;
        let t19 = x[4].mul_add(x[7], t5);
        let t20 = x[6].mul_add(x[9], t11);
        let t21 = t19 + t20;
        let t23 = (-t21).mul_add(T::from_i64(2), t18);
        t23
    }

    /// The norm, `sqrt(|norm_squared|)`.
    #[inline(always)]
    pub fn norm(self) -> T {
        self.norm_squared().abs().sqrt()
    }

    /// The inverse under the geometric product, by Shirokov's method in `Even` (no closed form
    /// for `Even` here): the inverse as a polynomial of degree 7 whose coefficients come
    /// from the scalar parts of powers (the FaddeevâLeVerrier recursion on left multiplication,
    /// 7 products in `Even`), then 1 NewtonâSchulz step(s) (docs/design.md, ADR-037). `x` is scaled to its largest
    /// coefficient first. Not finite where `x` has no inverse.
    #[inline]
    pub fn inverse(self) -> Even<(), T>
    where
        T: gx::Real,
    {
        T::vectorize(#[inline(always)] move || {
        let mut size = T::zero();
        for c in self.c {
            size = size.max(c.abs());
        }
        let scale = size.recip();
        let mut x = Even::<(), T>::zero();
        x.c[0] = self.c[0] * scale;
        x.c[1] = self.c[1] * scale;
        x.c[2] = self.c[2] * scale;
        x.c[3] = self.c[3] * scale;
        x.c[4] = self.c[4] * scale;
        x.c[5] = self.c[5] * scale;
        x.c[6] = self.c[6] * scale;
        x.c[7] = self.c[7] * scale;
        x.c[8] = self.c[8] * scale;
        x.c[9] = self.c[9] * scale;
        x.c[10] = self.c[10] * scale;
        x.c[11] = self.c[11] * scale;
        x.c[12] = self.c[12] * scale;
        x.c[13] = self.c[13] * scale;
        x.c[14] = self.c[14] * scale;
        x.c[15] = self.c[15] * scale;
        let a = x;
        // Uâ = a, Câ = (N/k) â¨Uââ©â, Uâââ = a (Uâ â Câ); then aâ»Â¹ = (U_{Nâ1} â C_{Nâ1}) / C_N.
        let mut prev = a;
        let c = a.c[0] * T::from_i64(8);
        prev.c[0] = prev.c[0] - c;
        for k in 2..8i64 {
            let u = a * prev;
            let c = u.c[0] * T::from_ratio(8, k);
            prev = u;
            prev.c[0] = prev.c[0] - c;
        }
        let det = (a * prev).c[0];
        let mut y = prev.gp(det.recip());
        // NewtonâSchulz, y â y (2 â x y), squares the residual: the recursion loses digits as
        // its degree grows (to 10â»â´ at degree 32), and the step(s) restore them.
        for _ in 0..1 {
            let mut t = -(x * y);
            t.c[0] = t.c[0] + T::from_i64(2);
            y = y * t;
        }
        y.gp(scale)
        })
    }

}

impl<T: gx::Real> gx::Log<Bivector<(), T>> for gx::Unit<Even<(), T>> {
    /// The logarithm of a unit versor: the bivector `B` with `B.exp() == self`.
    #[inline]
    #[allow(unused_variables)]
    fn log(self) -> Bivector<(), T> {
        T::vectorize(#[inline(always)] move || {
        let x = self.into_inner().c;
        let p1 = x[12] * x[12];
        let p3 = x[14] * x[15];
        let p4 = x[11].mul_add(x[11], p1);
        let p5 = x[13].mul_add(x[13], p4);
        let p7 = p3.mul_add(T::from_i64(2), p5);
        let p8 = -p7;
        let [h0, h1] = gx::study::log_coeffs_q(x[0], p8);
        let t0 = x[11] * h1;
        let t1 = x[12] * h1;
        let t2 = x[13] * h1;
        let t3 = x[14] * h1;
        let t4 = x[15] * h1;
        let t6 = x[4] * t4;
        let t8 = x[10] * t0;
        let t10 = x[5] * t4;
        let t12 = x[10] * t1;
        let t14 = x[6] * t4;
        let t16 = x[10] * t2;
        let t19 = x[5] * t2;
        let t20 = x[6] * t1;
        let t23 = x[5] * h0;
        let t24 = x[6] * t0;
        let t26 = x[4] * t1;
        let t28 = x[6] * h0;
        let t31 = x[8] * t2;
        let t32 = x[9] * t1;
        let t34 = x[7] * t2;
        let t36 = x[9] * t0;
        let t39 = x[8] * t0;
        let t40 = x[9] * h0;
        let t43 = x[3] * t2;
        let t44 = x[10] * h0;
        let t45 = x[1].mul_add(h0, t6);
        let t46 = x[7].mul_add(t3, t8);
        let t47 = t45 + t46;
        let t48 = x[2].mul_add(h0, t10);
        let t49 = x[8].mul_add(t3, t12);
        let t50 = t48 + t49;
        let t51 = x[3].mul_add(h0, t14);
        let t52 = x[9].mul_add(t3, t16);
        let t53 = t51 + t52;
        let t54 = x[4].mul_add(h0, t20);
        let t55 = x[1].mul_add(t3, t19);
        let t56 = t54 - t55;
        let t57 = x[4].mul_add(t2, t23);
        let t58 = x[2].mul_add(t3, t24);
        let t59 = t57 - t58;
        let t60 = x[5].mul_add(t0, t28);
        let t61 = x[3].mul_add(t3, t26);
        let t62 = t60 - t61;
        let t63 = x[7].mul_add(h0, t31);
        let t64 = x[1].mul_add(t4, t32);
        let t65 = t63 - t64;
        let t66 = x[8].mul_add(h0, t36);
        let t67 = x[2].mul_add(t4, t34);
        let t68 = t66 - t67;
        let t69 = x[7].mul_add(t1, t40);
        let t70 = x[3].mul_add(t4, t39);
        let t71 = t69 - t70;
        let t72 = (-x[1]).mul_add(t0, t44);
        let t73 = x[2].mul_add(t1, t43);
        let t74 = t72 - t73;
        Bivector::from_coeffs([t47, t50, t53, t56, t59, t62, t65, t68, t71, t74])
        })
    }
}

